mapper.select:
/* AppLogMapper.selectList */
SELECT A.AI_INPT_APPV_SRNO ,A.INPT_MST_SRNO ,A.AI_INPT_BIZ_DSCD ,A.AI_INPT_CRPE_ENO ,A.AI_INPT_PRC_DTM ,AI_INPT_PRC_OPI_TXT ,A.AI_INPT_TPY_SAVE_YN ,A.AI_INPT_APPV_STCD ,A.AI_INPT_TOTALTEXT_RST_CD ,A.AI_INPT_ITM_RST_CD ,A.AI_INPT_QLAS_PRC_STS_CD ,A.TRN_LOG_SRNO ,A.LST_DB_CHG_ID ,A.LST_DB_CHG_DTM FROM CSPD005TH A
ORDER BY A.INPT_MST_SRNO DESC

/* AppLogMapper.selectListTotCnt */
SELECT COUNT(*) totcnt
  FROM CSPD005TH A

mapper.update:
/* AppLogMapper.updateSantionApprvHis */
/* 결재승인시 결재이력 업데이트 */

MERGE INTO CSPD005TH A
  USING DUAL ON (
  	A.AI_INPT_APPV_SRNO = #{aiInptAppvHstId} AND A.INPT_MST_SRNO = #{inptMstSrno}
  )
WHEN MATCHED THEN
  UPDATE SET
    A.AI_INPT_CRPE_ENO = #{aiInptCrpeEno}
    , A.AI_INPT_PRC_OPI_TXT= #{aiInptStlOpiTxt} 
    , A.AI_INPT_APPV_STCD = #{appvPrgStcd} 
    , A.AI_INPT_TPY_SAVE_YN = #{aiInptTpySaveYn}
    , A.AI_INPT_PRC_DTM = (SELECT TO_CHAR(SYSTIMESTAMP, 'YYYYMMDDHH24MISSFF6') FROM DUAL) 
WHEN NOT MATCHED THEN
  INSERT (
  	A.AI_INPT_APPV_SRNO, A.INPT_MST_SRNO, A.AI_INPT_BIZ_DSCD
  	, A.AI_INPT_CRPE_ENO, AI_INPT_PRC_OPI_TXT, A.AI_INPT_TPY_SAVE_YN
  	, A.AI_INPT_APPV_STCD
  	, A.AI_INPT_TOTALTEXT_RST_CD, A.AI_INPT_ITM_RST_CD, A.AI_INPT_QLAS_PRC_STS_CD
  	, A.AI_INPT_PRC_DTM, A.LST_DB_CHG_ID, A.LST_DB_CHG_DTM
  )
  VALUES (
    CSPD005TH_SG01.NEXTVAL, #{inptMstSrno}, #{inptAtmcBizDscd}
    , #{aiInptCrpeEno}, #{aiInptStlOpiTxt}, #{aiInptTpySaveYn}
    , #{appvPrgStcd}
    , #{totaltextAiInptRstCd}, #{itmInptAiInptRstCd}, #{aiInptQlasPrgStsCd} 
    , (SELECT TO_CHAR(SYSTIMESTAMP, 'YYYYMMDDHH24MISSFF6') FROM DUAL), #{lstDbChgId}, (SELECT TO_CHAR(SYSTIMESTAMP, 'YYYYMMDDHH24MISSFF6') FROM DUAL)
  )
